160: async function _readWantedLockfile (
161:   pkgPath: string,
162:   opts: {
163:     wantedVersions?: string[]
164:     ignoreIncompatible: boolean
165:     useGitBranchLockfile?: boolean
166:     mergeGitBranchLockfiles?: boolean
167:     autofixMergeConflicts?: boolean
168:   }
169: ): Promise<{
170:     lockfile: Lockfile | null
171:     hadConflicts: boolean
172:   }> {
173:   const lockfileNames: string[] = [WANTED_LOCKFILE]
174:   if (opts.useGitBranchLockfile) {
175:     const gitBranchLockfileName: string = await getWantedLockfileName(opts)
176:     if (gitBranchLockfileName !== WANTED_LOCKFILE) {
177:       lockfileNames.unshift(gitBranchLockfileName)
178:     }
179:   }
180:   let result: { lockfile: Lockfile | null, hadConflicts: boolean } = { lockfile: null, hadConflicts: false }
181:   /* eslint-disable no-await-in-loop */
182:   for (const lockfileName of lockfileNames) {
183:     result = await _read(path.join(pkgPath, lockfileName), pkgPath, { ...opts, autofixMergeConflicts: true })
184:     if (result.lockfile) {
185:       if (opts.mergeGitBranchLockfiles) {
186:         result.lockfile = await _mergeGitBranchLockfiles(result.lockfile, pkgPath, pkgPath, opts)
187:       }
188:       break
189:     }
190:   }
191:   /* eslint-enable no-await-in-loop */
192:   return result
193: }
