195: async function _mergeGitBranchLockfiles (
196:   lockfile: Lockfile | null,
197:   lockfileDir: string,
198:   prefix: string,
199:   opts: {
200:     autofixMergeConflicts?: boolean
201:     wantedVersions?: string[]
202:     ignoreIncompatible: boolean
203:   }
204: ): Promise<Lockfile | null> {
205:   if (!lockfile) {
206:     return lockfile
207:   }
208:   const gitBranchLockfiles: Array<(Lockfile | null)> = (await _readGitBranchLockfiles(lockfileDir, prefix, opts)).map(({ lockfile }) => lockfile)
209: 
210:   let mergedLockfile: Lockfile = lockfile
211: 
212:   for (const gitBranchLockfile of gitBranchLockfiles) {
213:     if (!gitBranchLockfile) {
214:       continue
215:     }
216:     mergedLockfile = mergeLockfileChanges(mergedLockfile, gitBranchLockfile)
217:   }
218: 
219:   return mergedLockfile
220: }
