227:     wantedVersions?: string[]
228:     ignoreIncompatible: boolean
229:   }
230: ): Promise<Array<{
231:     lockfile: Lockfile | null
232:     hadConflicts: boolean
233:   }>> {
234:   const files = await getGitBranchLockfileNames(lockfileDir)
235: 
236:   return Promise.all(files.map((file) => _read(path.join(lockfileDir, file), prefix, opts)))
237: }
