253:       if (lockfileFile[depType] != null) {
254:         lockfileFile.importers['.'][depType] = lockfileFile[depType]
255:         delete lockfileFile[depType]
256:       }
257:     }
258:   }
259:   return lockfileFile as Lockfile
260: }
