180:         const suffixStart = ref.indexOf('(')
181:         const refWithoutPeerSuffix = suffixStart === -1 ? ref : ref.slice(0, suffixStart)
182:         const depPath = refToRelative(refWithoutPeerSuffix, depName)
183:         if (!depPath) continue
