214:         const suffixStart = ref.indexOf('_')
215:         const refWithoutPeerSuffix = suffixStart === -1 ? ref : ref.slice(0, suffixStart)
216:         const depPath = dp.refToRelative(refWithoutPeerSuffix, depName)
217:         if (!depPath) continue
218:         rootDepPaths.add(depPath)
219:       }
220:     }
221:   }
