225: export async function writeLockfiles (
226:   opts: {
227:     forceSharedFormat?: boolean
228:     wantedLockfile: Lockfile
229:     wantedLockfileDir: string
230:     currentLockfile: Lockfile
231:     currentLockfileDir: string
232:     useGitBranchLockfile?: boolean
233:     mergeGitBranchLockfiles?: boolean
234:   }
235: ) {
236:   const wantedLockfileName: string = await getWantedLockfileName(opts)
237:   const wantedLockfilePath = path.join(opts.wantedLockfileDir, wantedLockfileName)
238:   const currentLockfilePath = path.join(opts.currentLockfileDir, 'lock.yaml')
239: 
240:   const forceSharedFormat = opts?.forceSharedFormat === true
241:   const isLockfileV6 = opts.wantedLockfile.lockfileVersion.toString().startsWith('6.')
242:   const wantedLockfileToStringify = isLockfileV6
243:     ? convertToInlineSpecifiersFormat(opts.wantedLockfile) as unknown as Lockfile
244:     : opts.wantedLockfile
245:   const normalizeOpts = {
246:     forceSharedFormat,
247:     includeEmptySpecifiersField: !isLockfileV6,
248:   }
249:   const yamlDoc = yamlStringify(wantedLockfileToStringify, normalizeOpts)
250: 
251:   // in most cases the `pnpm-lock.yaml` and `node_modules/.pnpm-lock.yaml` are equal
252:   // in those cases the YAML document can be stringified only once for both files
253:   // which is more efficient
254:   if (opts.wantedLockfile === opts.currentLockfile) {
255:     await Promise.all([
256:       writeFileAtomic(wantedLockfilePath, yamlDoc),
257:       (async () => {
258:         if (isEmptyLockfile(opts.wantedLockfile)) {
259:           await rimraf(currentLockfilePath)
260:         } else {
261:           await fs.mkdir(path.dirname(currentLockfilePath), { recursive: true })
262:           await writeFileAtomic(currentLockfilePath, yamlDoc)
263:         }
264:       })(),
265:     ])
266:     return
267:   }
268: 
269:   logger.debug({
270:     message: `\`${WANTED_LOCKFILE}\` differs from \`${path.relative(opts.wantedLockfileDir, currentLockfilePath)}\``,
271:     prefix: opts.wantedLockfileDir,
272:   })
273: 
274:   const currentLockfileToStringify = opts.wantedLockfile.lockfileVersion.toString().startsWith('6.')
275:     ? convertToInlineSpecifiersFormat(opts.currentLockfile) as unknown as Lockfile
276:     : opts.currentLockfile
277:   const currentYamlDoc = yamlStringify(currentLockfileToStringify, normalizeOpts)
278: 
279:   await Promise.all([
280:     writeFileAtomic(wantedLockfilePath, yamlDoc),
281:     (async () => {
282:       if (isEmptyLockfile(opts.wantedLockfile)) {
283:         await rimraf(currentLockfilePath)
284:       } else {
285:         await fs.mkdir(path.dirname(currentLockfilePath), { recursive: true })
286:         await writeFileAtomic(currentLockfilePath, currentYamlDoc)
287:       }
288:     })(),
289:   ])
290: }
