28: export async function readLockfiles (
29:   opts: {
30:     autoInstallPeers: boolean
31:     excludeLinksFromLockfile: boolean
32:     force: boolean
33:     forceSharedLockfile: boolean
34:     frozenLockfile: boolean
35:     projects: Array<{
36:       id: string
37:       rootDir: string
38:     }>
39:     lockfileDir: string
40:     registry: string
41:     useLockfile: boolean
42:     useGitBranchLockfile?: boolean
43:     mergeGitBranchLockfiles?: boolean
44:     virtualStoreDir: string
45:   }
46: ): Promise<{
47:     currentLockfile: Lockfile
48:     currentLockfileIsUpToDate: boolean
49:     existsCurrentLockfile: boolean
50:     existsWantedLockfile: boolean
51:     existsNonEmptyWantedLockfile: boolean
52:     wantedLockfile: Lockfile
53:     wantedLockfileIsModified: boolean
54:     lockfileHadConflicts: boolean
55:   }> {
56:   const wantedLockfileVersion = LOCKFILE_VERSION_V6
57:   // ignore `pnpm-lock.yaml` on CI servers
58:   // a latest pnpm should not break all the builds
59:   const lockfileOpts = {
60:     ignoreIncompatible: opts.force || isCI,
61:     wantedVersions: [LOCKFILE_VERSION.toString(), LOCKFILE_VERSION_V6],
62:     useGitBranchLockfile: opts.useGitBranchLockfile,
63:     mergeGitBranchLockfiles: opts.mergeGitBranchLockfiles,
64:   }
65:   const fileReads = [] as Array<Promise<Lockfile | undefined | null>>
66:   let lockfileHadConflicts: boolean = false
67:   if (opts.useLockfile) {
68:     if (!opts.frozenLockfile) {
69:       fileReads.push(
70:         (async () => {
71:           try {
72:             const { lockfile, hadConflicts } = await readWantedLockfileAndAutofixConflicts(opts.lockfileDir, lockfileOpts)
73:             lockfileHadConflicts = hadConflicts
74:             return lockfile
75:           } catch (err: any) { // eslint-disable-line
76:             logger.warn({
77:               message: `Ignoring broken lockfile at ${opts.lockfileDir}: ${err.message as string}`,
78:               prefix: opts.lockfileDir,
79:             })
80:             return undefined
81:           }
82:         })()
83:       )
84:     } else {
85:       fileReads.push(readWantedLockfile(opts.lockfileDir, lockfileOpts))
86:     }
87:   } else {
88:     if (await existsNonEmptyWantedLockfile(opts.lockfileDir, lockfileOpts)) {
89:       logger.warn({
90:         message: `A ${WANTED_LOCKFILE} file exists. The current configuration prohibits to read or write a lockfile`,
91:         prefix: opts.lockfileDir,
92:       })
93:     }
94:     fileReads.push(Promise.resolve(undefined))
95:   }
96:   fileReads.push(
97:     (async () => {
98:       try {
99:         return await readCurrentLockfile(opts.virtualStoreDir, lockfileOpts)
100:       } catch (err: any) { // eslint-disable-line
101:         logger.warn({
102:           message: `Ignoring broken lockfile at ${opts.virtualStoreDir}: ${err.message as string}`,
103:           prefix: opts.lockfileDir,
104:         })
105:         return undefined
106:       }
107:     })()
108:   )
109:   const files = await Promise.all<Lockfile | null | undefined>(fileReads)
110:   const sopts = {
111:     autoInstallPeers: opts.autoInstallPeers,
112:     excludeLinksFromLockfile: opts.excludeLinksFromLockfile,
113:     lockfileVersion: wantedLockfileVersion,
114:   }
115:   const importerIds = opts.projects.map((importer) => importer.id)
116:   const currentLockfile = files[1] ?? createLockfileObject(importerIds, sopts)
117:   for (const importerId of importerIds) {
118:     if (!currentLockfile.importers[importerId]) {
119:       currentLockfile.importers[importerId] = {
120:         specifiers: {},
121:       }
122:     }
123:   }
124:   const wantedLockfile = files[0] ??
125:     (currentLockfile && clone(currentLockfile)) ??
126:     createLockfileObject(importerIds, sopts)
127:   let wantedLockfileIsModified = false
128:   for (const importerId of importerIds) {
129:     if (!wantedLockfile.importers[importerId]) {
130:       wantedLockfileIsModified = true
131:       wantedLockfile.importers[importerId] = {
132:         specifiers: {},
133:       }
134:     }
135:   }
136:   const existsWantedLockfile = files[0] != null
137:   return {
138:     currentLockfile,
139:     currentLockfileIsUpToDate: equals(currentLockfile, wantedLockfile),
140:     existsCurrentLockfile: files[1] != null,
141:     existsWantedLockfile,
142:     existsNonEmptyWantedLockfile: existsWantedLockfile && !isEmptyLockfile(wantedLockfile),
143:     wantedLockfile,
144:     wantedLockfileIsModified,
145:     lockfileHadConflicts,
146:   }
147: }
