13: 
14: export * from '@pnpm/lockfile-types'
15: 
16: export function pruneSharedLockfile (
17:   lockfile: Lockfile,
18:   opts?: {
19:     warn?: (msg: string) => void
20:   }
21: ) {
22:   const copiedPackages = (lockfile.packages == null)
23:     ? {}
24:     : copyPackageSnapshots(lockfile.packages, {
25:       devDepPaths: unnest(Object.values(lockfile.importers).map((deps) => resolvedDepsToDepPaths(deps.devDependencies ?? {}))),
26:       optionalDepPaths: unnest(Object.values(lockfile.importers).map((deps) => resolvedDepsToDepPaths(deps.optionalDependencies ?? {}))),
27:       prodDepPaths: unnest(Object.values(lockfile.importers).map((deps) => resolvedDepsToDepPaths(deps.dependencies ?? {}))),
28:       warn: opts?.warn ?? ((msg: string) => undefined),
29:     })
30: 
31:   const prunedLockfile: Lockfile = {
32:     ...lockfile,
33:     packages: copiedPackages,
34:   }
35:   if (isEmpty(prunedLockfile.packages)) {
36:     delete prunedLockfile.packages
37:   }
38:   return prunedLockfile
39: }
40: 
41: export function pruneLockfile (
42:   lockfile: Lockfile,
43:   pkg: PackageManifest,
44:   importerId: string,
45:   opts?: {
46:     warn?: (msg: string) => void
47:   }
48: ): Lockfile {
49:   const packages: PackageSnapshots = {}
50:   const importer = lockfile.importers[importerId]
51:   const lockfileSpecs: ResolvedDependencies = importer.specifiers ?? {}
52:   const optionalDependencies = Object.keys(pkg.optionalDependencies ?? {})
53:   const dependencies = difference(Object.keys(pkg.dependencies ?? {}), optionalDependencies)
54:   const devDependencies = difference(difference(Object.keys(pkg.devDependencies ?? {}), optionalDependencies), dependencies)
55:   const allDeps = new Set([
56:     ...optionalDependencies,
57:     ...devDependencies,
58:     ...dependencies,
59:   ])
60:   const specifiers: ResolvedDependencies = {}
61:   const lockfileDependencies: ResolvedDependencies = {}
62:   const lockfileOptionalDependencies: ResolvedDependencies = {}
63:   const lockfileDevDependencies: ResolvedDependencies = {}
64: 
65:   Object.entries(lockfileSpecs).forEach(([depName, spec]) => {
66:     if (!allDeps.has(depName)) return
67:     specifiers[depName] = spec
68:     if (importer.dependencies?.[depName]) {
69:       lockfileDependencies[depName] = importer.dependencies[depName]
70:     } else if (importer.optionalDependencies?.[depName]) {
71:       lockfileOptionalDependencies[depName] = importer.optionalDependencies[depName]
72:     } else if (importer.devDependencies?.[depName]) {
73:       lockfileDevDependencies[depName] = importer.devDependencies[depName]
74:     }
75:   })
76:   if (importer.dependencies != null) {
77:     for (const [alias, dep] of Object.entries(importer.dependencies)) {
78:       if (
79:         !lockfileDependencies[alias] && dep.startsWith('link:') &&
80:         // If the linked dependency was removed from package.json
81:         // then it is removed from pnpm-lock.yaml as well
82:         !(lockfileSpecs[alias] && !allDeps.has(alias))
83:       ) {
84:         lockfileDependencies[alias] = dep
85:       }
86:     }
87:   }
88: 
89:   const updatedImporter: ProjectSnapshot = {
90:     specifiers,
91:   }
92:   const prunedLockfile: Lockfile = {
93:     importers: {
94:       ...lockfile.importers,
95:       [importerId]: updatedImporter,
96:     },
97:     lockfileVersion: lockfile.lockfileVersion || LOCKFILE_VERSION,
98:     packages: lockfile.packages,
99:   }
100:   if (!isEmpty(packages)) {
101:     prunedLockfile.packages = packages
102:   }
103:   if (!isEmpty(lockfileDependencies)) {
104:     updatedImporter.dependencies = lockfileDependencies
105:   }
106:   if (!isEmpty(lockfileOptionalDependencies)) {
107:     updatedImporter.optionalDependencies = lockfileOptionalDependencies
108:   }
109:   if (!isEmpty(lockfileDevDependencies)) {
110:     updatedImporter.devDependencies = lockfileDevDependencies
111:   }
112:   return pruneSharedLockfile(prunedLockfile, opts)
113: }
114: 
115: function copyPackageSnapshots (
116:   originalPackages: PackageSnapshots,
117:   opts: {
118:     devDepPaths: string[]
119:     optionalDepPaths: string[]
120:     prodDepPaths: string[]
121:     warn: (msg: string) => void
122:   }
123: ): PackageSnapshots {
