125:   const ctx = {
126:     copiedSnapshots,
127:     nonOptional: new Set<string>(),
128:     notProdOnly: new Set<string>(),
129:     originalPackages,
130:     walked: new Set<string>(),
131:     warn: opts.warn,
132:   }
133: 
134:   copyDependencySubGraph(ctx, opts.devDepPaths, {
135:     dev: true,
136:     optional: false,
137:   })
138:   copyDependencySubGraph(ctx, opts.optionalDepPaths, {
139:     dev: false,
140:     optional: true,
141:   })
142:   copyDependencySubGraph(ctx, opts.prodDepPaths, {
143:     dev: false,
144:     optional: false,
145:   })
146: 
147:   return copiedSnapshots
148: }
149: 
150: function resolvedDepsToDepPaths (deps: ResolvedDependencies) {
151:   return Object.entries(deps)
152:     .map(([alias, ref]) => refToRelative(ref, alias))
153:     .filter((depPath) => depPath !== null) as string[]
154: }
