177:       // except local tarball dependencies
178:       if (depPath.startsWith('link:') || depPath.startsWith('file:') && !depPath.endsWith('.tar.gz')) continue
179: 
180:       ctx.warn(`Cannot find resolution of ${depPath} in lockfile`)
181:       continue
182:     }
183:     const depLockfile = ctx.originalPackages[depPath]
184:     ctx.copiedSnapshots[depPath] = depLockfile
185:     if (opts.optional && !ctx.nonOptional.has(depPath)) {
186:       depLockfile.optional = true
187:     } else {
188:       ctx.nonOptional.add(depPath)
189:       delete depLockfile.optional
190:     }
191:     if (opts.dev) {
192:       ctx.notProdOnly.add(depPath)
193:       depLockfile.dev = true
194:     } else if (depLockfile.dev === true) { // keeping if dev is explicitly false
195:       delete depLockfile.dev
196:     } else if (depLockfile.dev === undefined && !ctx.notProdOnly.has(depPath)) {
197:       depLockfile.dev = false
198:     }
199:     const newDependencies = resolvedDepsToDepPaths(depLockfile.dependencies ?? {})
200:     copyDependencySubGraph(ctx, newDependencies, opts)
201:     const newOptionalDependencies = resolvedDepsToDepPaths(depLockfile.optionalDependencies ?? {})
202:     copyDependencySubGraph(ctx, newOptionalDependencies, { dev: opts.dev, optional: true })
