{"text":"URL: https://demo.sourcegraph.com/github.com/sg-evals/pnpm--v8.15.9@4713381d81ad98e89eb597f73b99a8366408fdd6/-/blob/packages/make-dedicated-lockfile/src/index.ts
1: import path from 'path'
2: import pnpmExec from '@pnpm/exec'
3: import { createExportableManifest } from '@pnpm/exportable-manifest'
4: import {
5:   getLockfileImporterId,
6:   type ProjectSnapshot,
7:   readWantedLockfile,
8:   writeWantedLockfile,
9: } from '@pnpm/lockfile-file'
10: import { pruneSharedLockfile } from '@pnpm/prune-lockfile'
11: import { readProjectManifest } from '@pnpm/read-project-manifest'
12: import { DEPENDENCIES_FIELDS } from '@pnpm/types'
13: import pickBy from 'ramda/src/pickBy'
14: import renameOverwrite from 'rename-overwrite'
15: 
16: export async function makeDedicatedLockfile (lockfileDir: string, projectDir: string) {
17:   const lockfile = await readWantedLockfile(lockfileDir, { ignoreIncompatible: false })
18:   if (lockfile == null) {
19:     throw new Error('no lockfile found')
20:   }
21:   const allImporters = lockfile.importers
22:   lockfile.importers = {}
23:   const baseImporterId = getLockfileImporterId(lockfileDir, projectDir)
24:   for (const [importerId, importer] of Object.entries(allImporters)) {
25:     if (importerId.startsWith(`${baseImporterId}/`)) {
26:       const newImporterId = importerId.slice(baseImporterId.length + 1)
27:       lockfile.importers[newImporterId] = projectSnapshotWithoutLinkedDeps(importer)
28:       continue
29:     }
30:     if (importerId === baseImporterId) {
31:       lockfile.importers['.'] = projectSnapshotWithoutLinkedDeps(importer)
32:     }
33:   }
34:   const dedicatedLockfile = pruneSharedLockfile(lockfile)
35: 
36:   await writeWantedLockfile(projectDir, dedicatedLockfile)
37: 
38:   const { manifest, writeProjectManifest } = await readProjectManifest(projectDir)
39:   const publishManifest = await createExportableManifest(projectDir, manifest)
40:   await writeProjectManifest(publishManifest)
41: 
42:   const modulesDir = path.join(projectDir, 'node_modules')
43:   const tmp = path.join(projectDir, 'tmp_node_modules')
44:   const tempModulesDir = path.join(projectDir, 'node_modules/.tmp')
45:   let modulesRenamed = false
46:   try {
47:     await renameOverwrite(modulesDir, tmp)
48:     await renameOverwrite(tmp, tempModulesDir)
49:     modulesRenamed = true
50:   } catch (err: any) { // eslint-disable-line
51:     if (err['code'] !== 'ENOENT') throw err
52:   }
53: 
54:   try {
55:     await pnpmExec([
56:       'install',
57:       '--frozen-lockfile',
58:       '--lockfile-dir=.',
59:       '--fix-lockfile',
60:       '--filter=.',
61:       '--no-link-workspace-packages',
62:       '--config.dedupe-peer-dependents=false', // TODO: remove this. It should work without it
63:     ], {
64:       cwd: projectDir,
65:     })
66:   } finally {
67:     if (modulesRenamed) {
68:       await renameOverwrite(tempModulesDir, tmp)
69:       await renameOverwrite(tmp, modulesDir)
70:     }
71:     await writeProjectManifest(manifest)
72:   }
73: }
74: 
75: function projectSnapshotWithoutLinkedDeps (projectSnapshot: ProjectSnapshot) {
76:   const newProjectSnapshot: ProjectSnapshot = {
77:     specifiers: projectSnapshot.specifiers,
78:   }
79:   for (const depField of DEPENDENCIES_FIELDS) {
80:     if (projectSnapshot[depField] == null) continue
81:     newProjectSnapshot[depField] = pickBy((depVersion) => !depVersion.startsWith('link:'), projectSnapshot[depField])
82:   }
83:   return newProjectSnapshot
84: }
85: "}

