1: import { ENGINE_NAME } from '@pnpm/constants'
2: import { refToRelative } from '@pnpm/dependency-path'
3: import { type Lockfile } from '@pnpm/lockfile-types'
4: import { hashObjectWithoutSorting } from '@pnpm/crypto.object-hasher'
5: import sortKeys from 'sort-keys'
6: 
7: export interface DepsGraph {
8:   [depPath: string]: DepsGraphNode
9: }
10: 
11: export interface DepsGraphNode {
12:   children: { [alias: string]: string }
13:   depPath: string
14: }
15: 
16: export interface DepsStateCache {
17:   [depPath: string]: DepStateObj
18: }
19: 
20: export interface DepStateObj {
21:   [depPath: string]: DepStateObj
22: }
23: 
24: export function calcDepState (
25:   depsGraph: DepsGraph,
26:   cache: DepsStateCache,
27:   depPath: string,
28:   opts: {
29:     patchFileHash?: string
30:     isBuilt: boolean
31:   }
32: ): string {
33:   let result = ENGINE_NAME
34:   if (opts.isBuilt) {
35:     const depStateObj = calcDepStateObj(depPath, depsGraph, cache, new Set())
36:     result += `-${hashObjectWithoutSorting(depStateObj)}`
37:   }
38:   if (opts.patchFileHash) {
39:     result += `-${opts.patchFileHash}`
40:   }
41:   return result
42: }
43: 
44: function calcDepStateObj (
45:   depPath: string,
46:   depsGraph: DepsGraph,
47:   cache: DepsStateCache,
48:   parents: Set<string>
49: ): DepStateObj {
50:   if (cache[depPath]) return cache[depPath]
51:   const node = depsGraph[depPath]
52:   if (!node) return {}
53:   const nextParents = new Set([...Array.from(parents), node.depPath])
54:   const state: DepStateObj = {}
55:   for (const childId of Object.values(node.children)) {
56:     const child = depsGraph[childId]
57:     if (!child) continue
58:     if (parents.has(child.depPath)) {
59:       state[child.depPath] = {}
60:       continue
61:     }
62:     state[child.depPath] = calcDepStateObj(childId, depsGraph, cache, nextParents)
63:   }
64:   cache[depPath] = sortKeys(state)
65:   return cache[depPath]
66: }
67: 
68: export function lockfileToDepGraph (lockfile: Lockfile): DepsGraph {
69:   const graph: DepsGraph = {}
70:   if (lockfile.packages != null) {
71:     Object.entries(lockfile.packages).map(async ([depPath, pkgSnapshot]) => {
72:       const children = lockfileDepsToGraphChildren({
73:         ...pkgSnapshot.dependencies,
74:         ...pkgSnapshot.optionalDependencies,
75:       })
76:       graph[depPath] = {
77:         children,
78:         depPath,
79:       }
80:     })
81:   }
82:   return graph
83: }
84: 
85: function lockfileDepsToGraphChildren (deps: Record<string, string>): Record<string, string> {
86:   const children: Record<string, string> = {}
87:   for (const [alias, reference] of Object.entries(deps)) {
88:     const depPath = refToRelative(reference, alias)
89:     if (depPath) {
90:       children[alias] = depPath
91:     }
92:   }
93:   return children
94: }
95: "}

