1: import url from 'url'
2: import { type PackageSnapshot, type TarballResolution } from '@pnpm/lockfile-types'
3: import { type Resolution } from '@pnpm/resolver-base'
4: import { type Registries } from '@pnpm/types'
5: import * as dp from '@pnpm/dependency-path'
6: import getNpmTarballUrl from 'get-npm-tarball-url'
7: import { isGitHostedPkgUrl } from '@pnpm/pick-fetcher'
8: import { nameVerFromPkgSnapshot } from './nameVerFromPkgSnapshot'
9: 
10: export function pkgSnapshotToResolution (
11:   depPath: string,
12:   pkgSnapshot: PackageSnapshot,
13:   registries: Registries
14: ): Resolution {
15:   if (
16:     Boolean((pkgSnapshot.resolution as TarballResolution).type) ||
17:     (pkgSnapshot.resolution as TarballResolution).tarball?.startsWith('file:') ||
18:     isGitHostedPkgUrl((pkgSnapshot.resolution as TarballResolution).tarball ?? '')
19:   ) {
20:     return pkgSnapshot.resolution as Resolution
21:   }
22:   const { name } = nameVerFromPkgSnapshot(depPath, pkgSnapshot)
23:   let registry: string = ''
24:   if (name != null) {
25:     if (name.startsWith('@')) {
26:       registry = registries[name.split('/')[0]]
27:     }
28:   }
29:   if (!registry) {
30:     registry = registries.default
31:   }
32:   let tarball!: string
33:   if (!(pkgSnapshot.resolution as TarballResolution).tarball) {
34:     tarball = getTarball(registry)
35:   } else {
36:     tarball = new url.URL((pkgSnapshot.resolution as TarballResolution).tarball,
37:       registry.endsWith('/') ? registry : `${registry}/`
38:     ).toString()
39:   }
40:   return {
41:     ...pkgSnapshot.resolution,
42:     tarball,
43:   } as Resolution
44: 
45:   function getTarball (registry: string) {
46:     const { name, version } = dp.parse(depPath)
47:     if (!name || !version) {
48:       throw new Error(`Couldn't get tarball URL from dependency path ${depPath}`)
49:     }
50:     return getNpmTarballUrl(name, version, { registry })
51:   }
52: }
53: "}

